  return (log(x));
}

real invf(real x) {
  return (exp(x));
}

real x;

draw((-5,0)--(5,0),Arrows(6));
draw((0,-5)--(0,5),Arrows(6));

label("$x$", (5,0), E);
label("$y$", (0,5), N);

draw(graph(func,-1,0),red);
draw(graph(func,1,5),red);
draw(graph(invf,-1,0),red);
draw(graph(invf,1,5),red);

label("$y = f(x)$", (-1,-2), UnFill);
[/asy]
[/mathext]
